draw:
var fontS = "12px ui-sans-serif, system-ui, sans-serif";
var L = p.len;                 // metres
var d = p.dia * 0.001;         // mm -> m
var rho = p.rho * 1e-8;
var A = Math.PI * d * d / 4;
var R = rho * L / A;
var I = 5.0;
var n = 8.5e28, e = 1.6e-19;
var vd = I / (n * e * A);

var x0 = W * 0.12, x1 = W * 0.12 + (W * 0.76) * (L / 40);
if (x1 < x0 + 8) x1 = x0 + 8;
var midY = H * 0.38;
var hpx = 6 + 26 * (p.dia / 4);

ctx.fillStyle = C.figure;
ctx.fillRect(x0, midY - hpx / 2, x1 - x0, hpx);

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(W * 0.04, midY); ctx.lineTo(x0, midY); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x1, midY); ctx.lineTo(W * 0.96, midY); ctx.stroke();

// drifting carriers
ctx.fillStyle = C.accent;
var k;
for (k = 0; k < 9; k++) {
  var frac = ((t * 0.09 * (5 / (L)) ) + k / 9) % 1;
  var cx = x0 + frac * (x1 - x0);
  ctx.beginPath(); ctx.arc(cx, midY, 2.5, 0, Math.PI * 2); ctx.fill();
}

// length dimension line
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(x0, midY + hpx / 2 + 14); ctx.lineTo(x1, midY + hpx / 2 + 14);
ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, midY + hpx / 2 + 10); ctx.lineTo(x0, midY + hpx / 2 + 18); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x1, midY + hpx / 2 + 10); ctx.lineTo(x1, midY + hpx / 2 + 18); ctx.stroke();

ctx.font = fontS;
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("L = " + L.toFixed(1) + " m", (x0 + x1) / 2, midY + hpx / 2 + 30);
ctx.textAlign = "left";
ctx.fillText("area A = " + (A * 1e6).toFixed(3) + " mm^2", W * 0.12, H * 0.14);
ctx.fillText("current I = 5.0 A (fixed)", W * 0.12, H * 0.14 + 16);

// bar comparing R
var by = H * 0.82;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(W * 0.12, by); ctx.lineTo(W * 0.88, by); ctx.stroke();
var frac2 = R / 2.0; if (frac2 > 1) frac2 = 1;
ctx.fillStyle = C.accent;
ctx.fillRect(W * 0.12, by - 10, (W * 0.76) * frac2, 10);
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("R on a 0 to 2 ohm scale", W * 0.12, by + 16);

out.note = "R = " + R.toFixed(4) + " ohm, drift speed = " + (vd * 1000).toFixed(4) + " mm/s, voltage drop at 5 A = " + (5 * R).toFixed(3) + " V";

var fontS = "12px ui-sans-serif, system-ui, sans-serif";
ctx.font = fontS;
var step = Math.round(p.step);
var midY = H * 0.45;
var xA = W * 0.30, xB = W * 0.66;
var x0 = W * 0.08, x1 = W * 0.92;
var gap = H * 0.16;

function box(cx, cy, label) {
  var w = W * 0.11, h = 18;
  ctx.fillStyle = C.paper;
  ctx.fillRect(cx - w / 2, cy - h / 2, w, h);
  ctx.strokeStyle = C.figure;
  ctx.lineWidth = 2;
  ctx.strokeRect(cx - w / 2, cy - h / 2, w, h);
  ctx.fillStyle = C.ink;
  ctx.textAlign = "center";
  ctx.fillText(label, cx, cy - h / 2 - 6);
  return w;
}

function wire(ax, ay, bx, by) {
  ctx.strokeStyle = C.rule;
  ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(bx, by); ctx.stroke();
}

var Req;
if (step === 0) {
  Req = 10.0;
  wire(x0, midY, xA, midY);
  wire(xA, midY, xA, midY - gap); wire(xA, midY, xA, midY + gap);
  wire(xA, midY - gap, xB, midY - gap);
  wire(xA, midY + gap, xB, midY + gap);
  wire(xB, midY - gap, xB, midY); wire(xB, midY + gap, xB, midY);
  wire(xB, midY, x1, midY);
  box((x0 + xA) / 2, midY, "4.0 ohm");
  box((xA + xB) / 2, midY - gap, "6.0 ohm");
  box((xA + xB) / 2, midY + gap, "12.0 ohm");
  box((xB + x1) / 2, midY, "2.0 ohm");
  ctx.fillStyle = C.accent;
  ctx.textAlign = "center";
  ctx.fillText("A", xA, midY + 22);
  ctx.fillText("B", xB, midY + 22);
} else if (step === 1) {
  Req = 10.0;
  wire(x0, midY, x1, midY);
  box(W * 0.20, midY, "4.0 ohm");
  box(W * 0.50, midY, "6 || 12 = 4.0 ohm");
  box(W * 0.80, midY, "2.0 ohm");
  ctx.fillStyle = C.accent;
  ctx.textAlign = "center";
  ctx.fillText("A", W * 0.345, midY + 22);
  ctx.fillText("B", W * 0.655, midY + 22);
} else {
  Req = 10.0;
  wire(x0, midY, x1, midY);
  box(W * 0.50, midY, "10.0 ohm total");
}

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
var titles = ["Step 0: the network as drawn", "Step 1: the parallel pair replaced", "Step 2: the chain added up"];
ctx.fillText(titles[step], W * 0.08, H * 0.14);

ctx.fillStyle = C.faint;
ctx.fillText("battery terminals at the far left and far right", W * 0.08, H * 0.88);

out.note = "Equivalent resistance = " + Req.toFixed(1) + " ohm, so a 12.0 V battery drives " + (12.0 / Req).toFixed(2) + " A";

var fontS = "12px ui-sans-serif, system-ui, sans-serif";
ctx.font = fontS;
var emf = 24.0, rint = 0.5, rcab = 1.5;
var rfix = rint + rcab;
var RL = p.load;
var I = emf / (RL + rfix);
var P = I * I * RL;
var Pmax = emf * emf / (4 * rfix);

// circuit strip along the top
var ty = H * 0.16;
ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(W * 0.08, ty); ctx.lineTo(W * 0.92, ty); ctx.stroke();
ctx.fillStyle = C.ink; ctx.textAlign = "center";
ctx.fillText("emf 24.0 V", W * 0.16, ty - 8);
ctx.fillText("r = 0.5 ohm", W * 0.36, ty - 8);
ctx.fillText("cable 1.5 ohm", W * 0.58, ty - 8);
ctx.fillText("load " + RL.toFixed(2) + " ohm", W * 0.82, ty - 8);
ctx.fillStyle = C.figure;
ctx.fillRect(W * 0.31, ty - 5, W * 0.10, 10);
ctx.fillRect(W * 0.53, ty - 5, W * 0.10, 10);
ctx.fillStyle = C.accent;
ctx.fillRect(W * 0.77, ty - 5, W * 0.10, 10);

// axes
var ox = W * 0.14, oy = H * 0.88, gw = W * 0.78, gh = H * 0.56;
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(ox + gw, oy); ctx.stroke();
ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(ox, oy - gh); ctx.stroke();
ctx.fillStyle = C.ink; ctx.textAlign = "center";
ctx.fillText("load resistance R (ohm)", ox + gw / 2, oy + 18);
ctx.save();
ctx.translate(ox - 26, oy - gh / 2);
ctx.rotate(-Math.PI / 2);
ctx.fillText("power in load (W)", 0, 0);
ctx.restore();

var Rmax = 12.0;
// curve
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath();
var i;
for (i = 0; i <= 160; i++) {
  var rr = 0.02 + Rmax * i / 160;
  var ii = emf / (rr + rfix);
  var pp = ii * ii * rr;
  var px = ox + gw * (rr / Rmax);
  var py = oy - gh * (pp / (Pmax * 1.1));
  if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
}
ctx.stroke();

// peak marker
var peakX = ox + gw * (rfix / Rmax);
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(peakX, oy); ctx.lineTo(peakX, oy - gh * (Pmax / (Pmax * 1.1))); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint; ctx.textAlign = "left";
ctx.fillText("R = r + cable = 2.0 ohm", peakX + 6, oy - gh * 0.98);

// live point
var cx = ox + gw * (RL / Rmax);
var cy = oy - gh * (P / (Pmax * 1.1));
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cx, cy, 4.5, 0, Math.PI * 2); ctx.fill();

out.note = "I = " + I.toFixed(2) + " A, load power = " + P.toFixed(1) + " W of a possible " + Pmax.toFixed(1) + " W, efficiency = " + (100 * RL / (RL + rfix)).toFixed(0) + " percent";
